:root {
  --bg: #f5f7fb;
  --panel: #ffffff;
  --grid: #1f2937;
  --x: #2563eb;
  --o: #dc2626;
  --text: #111827;
  --muted: #4b5563;
  --accent: #10b981;
  --shadow: rgba(15, 23, 42, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: linear-gradient(180deg, #eef4ff 0%, #f9fafb 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

.app {
  width: min(92vw, 420px);
  background: var(--panel);
  border-radius: 18px;
  padding: 1.5rem 1.25rem 1.25rem;
  box-shadow: 0 18px 45px var(--shadow);
  text-align: center;
}

h1 {
  margin: 0 0 0.5rem;
  font-size: clamp(1.9rem, 4vw, 2.5rem);
}

.tagline {
  margin: 0 0 1rem;
  color: var(--muted);
  line-height: 1.4;
}

.status {
  min-height: 1.5rem;
  margin-bottom: 1rem;
  font-weight: 700;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  background: var(--grid);
  padding: 0.5rem;
  border-radius: 14px;
}

.cell {
  appearance: none;
  border: none;
  background: #f8fafc;
  color: var(--text);
  aspect-ratio: 1;
  font-size: clamp(2.2rem, 8vw, 3.2rem);
  font-weight: 700;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.12s ease;
}

.cell:hover:not(:disabled) {
  background: #edf2ff;
  transform: translateY(-1px);
}

.cell:disabled {
  cursor: default;
}

.cell.x {
  color: var(--x);
}

.cell.o {
  color: var(--o);
}

.reset {
  margin-top: 1rem;
  width: 100%;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: white;
  font-size: 1rem;
  font-weight: 700;
  padding: 0.8rem 1rem;
  cursor: pointer;
}

.reset:hover {
  filter: brightness(1.02);
}

const cells = Array.from(document.querySelectorAll('.cell'));
const statusEl = document.getElementById('status');
const resetButton = document.getElementById('reset');

const winningLines = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6],
];

let board = Array(9).fill(null);
let currentPlayer = 'X';
let gameOver = false;

function setStatus(message) {
  statusEl.textContent = message;
}

function getWinner(boardState) {
  for (const [a, b, c] of winningLines) {
    if (boardState[a] && boardState[a] === boardState[b] && boardState[a] === boardState[c]) {
      return boardState[a];
    }
  }

  return null;
}

function isBoardFull(boardState) {
  return boardState.every(Boolean);
}

function renderBoard() {
  cells.forEach((cell, index) => {
    const mark = board[index];
    cell.textContent = mark || '';
    cell.classList.toggle('x', mark === 'X');
    cell.classList.toggle('o', mark === 'O');
    cell.disabled = Boolean(mark) || gameOver;
  });
}

function endGame(winnerLabel) {
  gameOver = true;
  setStatus(winnerLabel);
  renderBoard();
}

function handleCellClick(event) {
  const index = Number(event.currentTarget.dataset.index);

  if (gameOver || board[index]) {
    return;
  }

  board[index] = currentPlayer;
  renderBoard();

  const winner = getWinner(board);
  if (winner) {
    endGame(`${winner} wins!`);
    return;
  }

  if (isBoardFull(board)) {
    endGame(`${currentPlayer} wins by the board lock!`);
    return;
  }

  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  setStatus(`Player ${currentPlayer}'s turn`);
}

function resetGame() {
  board = Array(9).fill(null);
  currentPlayer = 'X';
  gameOver = false;
  setStatus("Player X's turn");
  renderBoard();
}

cells.forEach((cell) => {
  cell.addEventListener('click', handleCellClick);
});

resetButton.addEventListener('click', resetGame);

renderBoard();

